// pt_lang.cpp - switches the game's built-in text to another language (pt_lang.h).
//
// Every language's text is compiled into the game (lang_*.cpp, generated by
// web\gen_lang.py). Switching first copies English back into the live variables,
// then the chosen language over it, so anything a language lacks stays English.
// Copies are by variable name and bounded by both sides' sizes; a missing (null)
// string never replaces one that is there. The text renderer is told the language's
// code page (ptgfx_text.cpp g_PtTextCodePage), since each language's text is in its
// own Windows code page.

#include "pt_lang_tu.h"
#include <stdio.h>
#include <string.h>
#include <string>
#include <map>

extern const PtLangTable PtLang_LIVE_Table, PtLang_EN_Table, PtLang_KO_Table, PtLang_JP_Table, PtLang_CN_Table,
	PtLang_TW_Table, PtLang_TH_Table, PtLang_VN_Table, PtLang_BR_Table, PtLang_AR_Table;

static const PtLangTable *s_Tables[PT_LANG_COUNT] = {
	&PtLang_EN_Table, &PtLang_KO_Table, &PtLang_JP_Table, &PtLang_CN_Table, &PtLang_TW_Table,
	&PtLang_TH_Table, &PtLang_VN_Table, &PtLang_BR_Table, &PtLang_AR_Table };

extern UINT g_PtTextCodePage;			// ptgfx_text.cpp: 0 = the font's own

static int s_Lang = PT_LANG_ENGLISH;

int PtLang_Get() { return s_Lang; }

static void CopyChars( char *d, int width, const char *s )
{
	if ( !s || width<=0 ) return;
	strncpy( d, s, width-1 );
	d[width-1] = 0;
}

// a string from a source entry, or NULL
static const char *SourceString( const PtLangEntry &s, int i )
{
	if ( i>=s.count ) return NULL;
	if ( s.kind==PT_LANGK_PTR ) return ((char **)s.addr)[i];
	if ( s.kind==PT_LANGK_CHARS ) return (char *)s.addr + i*s.width;
	return NULL;
}

static void CopyEntry( const PtLangEntry &d, const PtLangEntry &s )
{
	int i, n = d.count<s.count ? d.count : s.count;
	switch ( d.kind ) {
	case PT_LANGK_PTR:
		// a pointer can take the source's string wherever it lives (both are static)
		for ( i=0; i<n; i++ ) {
			const char *str = SourceString( s, i );
			if ( str ) ((char **)d.addr)[i] = (char *)str;
		}
		break;
	case PT_LANGK_CHARS:
		for ( i=0; i<n; i++ ) CopyChars( (char *)d.addr + i*d.width, d.width, SourceString( s, i ) );
		break;
	case PT_LANGK_MSGBOX:
		if ( s.kind!=d.kind ) break;
		for ( i=0; i<n; i++ ) {
			sMESSAGEBOX *dm = (sMESSAGEBOX *)d.addr + i, *sm = (sMESSAGEBOX *)s.addr + i;
			CopyChars( dm->MessageDoc, sizeof(dm->MessageDoc), sm->MessageDoc );
			CopyChars( dm->MessageDoc2, sizeof(dm->MessageDoc2), sm->MessageDoc2 );
		}
		break;
	case PT_LANGK_MSGBOX2:
		if ( s.kind!=d.kind ) break;
		for ( i=0; i<n; i++ ) {
			sMESSAGEBOX2 *dm = (sMESSAGEBOX2 *)d.addr + i, *sm = (sMESSAGEBOX2 *)s.addr + i;
			CopyChars( dm->MessageDoc1, sizeof(dm->MessageDoc1), sm->MessageDoc1 );
			CopyChars( dm->MessageDoc2, sizeof(dm->MessageDoc2), sm->MessageDoc2 );
		}
		break;
	case PT_LANGK_MSGBOX3:
		if ( s.kind!=d.kind ) break;
		for ( i=0; i<n; i++ ) {
			sMESSAGEBOX3 *dm = (sMESSAGEBOX3 *)d.addr + i, *sm = (sMESSAGEBOX3 *)s.addr + i;
			CopyChars( dm->MessageDoc1, sizeof(dm->MessageDoc1), sm->MessageDoc1 );
			CopyChars( dm->MessageDoc2, sizeof(dm->MessageDoc2), sm->MessageDoc2 );
		}
		break;
	}
}

// Skill names and descriptions, matched by skill code. The numbers (levels, mana,
// damage) are never touched: the server and the skill checksum rely on them.
static void CopySkills( sSKILL_INFO *d, const sSKILL_INFO *s )
{
	for ( int i=0; i<SIN_MAX_SKILL; i++ ) {
		if ( !d[i].CODE ) continue;
		for ( int j=0; j<SIN_MAX_SKILL; j++ ) {
			if ( s[j].CODE!=d[i].CODE ) continue;
			if ( s[j].SkillName[0] ) CopyChars( d[i].SkillName, sizeof(d[i].SkillName), s[j].SkillName );
			if ( s[j].SkillDoc[0] ) CopyChars( d[i].SkillDoc, sizeof(d[i].SkillDoc), s[j].SkillDoc );
			break;
		}
	}
}

// Crafting descriptions, matched by the recipe (items, sheltoms and what it adds)
static void CopyCrafts( sCRAFTITEM_INFO *d, const sCRAFTITEM_INFO *s )
{
	for ( int i=0; i<MAX_CRAFTITEM_INFO; i++ ) {
		if ( !d[i].MainItemCode[0] ) continue;
		for ( int j=0; j<MAX_CRAFTITEM_INFO; j++ ) {
			if ( memcmp( d[i].MainItemCode, s[j].MainItemCode, sizeof(d[i].MainItemCode) ) ||
				memcmp( d[i].AddItem, s[j].AddItem, sizeof(d[i].AddItem) ) ||
				memcmp( d[i].PlusElementCode, s[j].PlusElementCode, sizeof(d[i].PlusElementCode) ) ) continue;
			if ( s[j].Doc[0] ) CopyChars( d[i].Doc, sizeof(d[i].Doc), s[j].Doc );
			break;
		}
	}
}

// Class names as shown (szName2), matched by class code. szName stays English: the
// game data names classes in English and fileread.cpp matches against szName.
static void CopyJobs( JOB_DATA_CODE *d, const JOB_DATA_CODE *s )
{
	for ( int i=0; d[i].szName && d[i].szName[0]; i++ ) {
		for ( int j=0; s[j].szName && s[j].szName[0]; j++ ) {
			if ( s[j].JobCode!=d[i].JobCode || s[j].JobBitCode!=d[i].JobBitCode ) continue;
			if ( s[j].szName2 && s[j].szName2[0] ) d[i].szName2 = s[j].szName2;
			break;
		}
	}
}

// returns how many of the game's text variables the language had
static int Apply( const PtLangTable &live, const PtLangTable &src )
{
	std::map<std::string, const PtLangEntry *> byName;
	int found = 0;
	for ( int i=0; i<src.nEntries; i++ ) byName[src.entries[i].name] = &src.entries[i];
	for ( int i=0; i<live.nEntries; i++ ) {
		std::map<std::string, const PtLangEntry *>::iterator it = byName.find( live.entries[i].name );
		if ( it==byName.end() ) continue;
		CopyEntry( live.entries[i], *it->second );
		found++;
	}
	if ( src.skills ) CopySkills( live.skills, src.skills );
	if ( src.crafts ) CopyCrafts( live.crafts, src.crafts );
	if ( src.jobs ) CopyJobs( live.jobs, src.jobs );
	return found;
}

// The page log line for a switch, with one message as the renderer will decode it
static void LogSwitch( const PtLangTable &t, int found )
{
	char utf8[256] = "";
	WCHAR w[128];
	const char *sample = HoTextLoginMessage[0];
	int n = MultiByteToWideChar( t.codePage, 0, sample, (int)strlen( sample ), w, 127 );
	if ( n>0 ) utf8[ WideCharToMultiByte( CP_UTF8, 0, w, n, utf8, sizeof(utf8)-1, 0, 0 ) ] = 0;
	printf( "[lang] %s: %d of %d texts, code page %u, login message: \"%s\"\n", t.code, found, PtLang_LIVE_Table.nEntries, t.codePage, utf8 );
}

int PtLang_Set( int lang )
{
	if ( lang<0 || lang>=PT_LANG_COUNT || lang==s_Lang ) return FALSE;
	int found = Apply( PtLang_LIVE_Table, PtLang_EN_Table );
	if ( lang!=PT_LANG_ENGLISH ) found = Apply( PtLang_LIVE_Table, *s_Tables[lang] );
	g_PtTextCodePage = lang==PT_LANG_ENGLISH ? 0 : s_Tables[lang]->codePage;
	s_Lang = lang;
	LogSwitch( *s_Tables[lang], found );
	return TRUE;
}
